import { generateTagFile } from './reference-openroll.ts';


const result = await generateTagFile({
    mediaType: 1,
    widthMm: 50,
    heightMm: 30,
    gapMm: 6,
    nominalQuantity: 230,
    uid: '1D:E1:A1:93:10:10:80',
    tagType: 'NTAG213',
    format: 'raw',
});

function assert(condition: boolean, message: string) {
    if (!condition) {
        throw new Error(message);
    }
}
const GOLDEN_BINARY_STRING = ''

const goldenBytes = new Uint8Array(GOLDEN_BINARY_STRING.match(/.{1,2}/g)!.map(byte => parseInt(byte, 16)));

assert(result.bytes.length === goldenBytes.length, `Expected byte length ${goldenBytes.length}, got ${result.bytes.length}`);
for (let i = 0; i < goldenBytes.length; i++) {
    assert(result.bytes[i] === goldenBytes[i], `Byte mismatch at index ${i}: expected ${goldenBytes[i]}, got ${result.bytes[i]}`);
}

console.log('Test passed: Generated bytes match the golden reference.');